/* =====================================================================
 * 金鶯診所 · 醫師基準班表系統 — 共用核心 engine.js
 *  - 解析集團門診表（Google Sheet 各院區分頁）
 *  - 判定各院區適用的「基準版本」（XX門診 M/D開始）
 *  - 彙整每位醫師的個人基準班表
 *  - 以 Canvas 繪製個人班表圖卡（PNG）
 * 前台 index.html、後台 admin.html 共用，一定要一起上傳。
 * ===================================================================== */
(function (root) {
  'use strict';
  const E = {};
  E.LOGO = 'data:image/png;base64,';
  E.DAYS = ['星期一', '星期二', '星期三', '星期四', '星期五', '星期六', '星期日'];
  E.SESS = ['早', '午', '晚'];
  E.TITLES = ['總院長', '院長', '醫師'];

  /* 系統設定預設值（後台「系統設定」分頁可覆寫） */
  E.DEFAULTS = {
    specialKeywords: '減重,超音波,專診',   // A 欄診別含這些字 → 特別門診（名稱＋時間區間格式）
    containHide: 'Y',                     // 特別門診時段完全包含在同院區同日的健保門診內 → 不另外顯示
    noonStart: '12:00',                   // 特別門診：開始時間 ≥ 此值歸「午」
    nightStart: '17:00',                  // 特別門診：開始時間 ≥ 此值歸「晚」
    notice: '異動班表以公告為主',
    homeLabel: '專任院區',
    otherLabel: '非專任院區',
    footer: 'Elite Clinic',
    watermark: 0.06,
    showLegend: 'Y'
  };
  E.settings = function (rows) {
    const s = Object.assign({}, E.DEFAULTS);
    (rows || []).forEach(r => { if (r && r.key in s && r.value !== '' && r.value !== undefined && r.value !== null) s[r.key] = r.value; });
    s.watermark = +s.watermark || 0;
    return s;
  };

  /* ---------------------------- 小工具 ---------------------------- */
  const CJK = /^[\u3400-\u9fff\uf900-\ufaff]{2,5}$/;
  const STOP = /^(休診|停診|公休|休息|休假|國定假日|假日|待聘|徵才|支援|星期[一二三四五六日天])$/;
  const toHalf = s => String(s).replace(/[\uff01-\uff5e]/g, ch => String.fromCharCode(ch.charCodeAt(0) - 0xfee0)).replace(/\u3000/g, ' ');
  function cellText(v) {
    if (v === undefined || v === null) return '';
    let s = String(v);
    if (s.startsWith('T:')) s = s.slice(2);
    s = toHalf(s).trim();
    // 「上午 7:30:00」「下午 6:30」「7:30 PM」→ 24 小時制
    const ap = s.match(/^(上午|下午|AM|PM)\s*(\d{1,2}):(\d{2})(?::\d{2})?$/i) || s.match(/^(\d{1,2}):(\d{2})(?::\d{2})?\s*(AM|PM)$/i);
    if (ap) {
      const pm = /下午|PM/i.test(s), h0 = +(ap[2] && /^\d/.test(ap[2]) && ap[1].length > 2 || /上午|下午/.test(ap[1]) || /^(AM|PM)$/i.test(ap[1]) ? ap[2] : ap[1]);
      const mm = /上午|下午/.test(ap[1]) || /^(AM|PM)$/i.test(ap[1]) ? ap[3] : ap[2];
      let h = h0 % 12 + (pm ? 12 : 0);
      s = h + ':' + mm;
    }
    return s;
  }
  E.cellText = cellText;
  const isDate = v => typeof v === 'string' && (v.startsWith('D:') || /^\d{4}[\/\-.]\d{1,2}[\/\-.]\d{1,2}/.test(v.trim()));
  const dateIso = v => { if (v.startsWith('D:')) return v.slice(2); const m = v.trim().match(/^(\d{4})[\/\-.](\d{1,2})[\/\-.](\d{1,2})/); return m[1] + '-' + ('0' + m[2]).slice(-2) + '-' + ('0' + m[3]).slice(-2); };
  const isTilde = v => /^[~～〜\-－—]$/.test(cellText(v));

  /** "7:30" "07:30" "7:30:00" "8.5" "15" → 分鐘 */
  function hm(s) {
    s = toHalf(String(s)).trim().replace(/^T:/, '');
    let m = s.match(/^(\d{1,2})[:：](\d{2})(?::\d{2})?$/);
    if (m) return +m[1] * 60 + +m[2];
    m = s.match(/^(\d{1,2})(?:\.(\d+))?$/);
    if (m) { const h = +m[1], f = m[2] ? +('0.' + m[2]) : 0; return Math.round((h + f) * 60); }
    return null;
  }
  E.hm = hm;
  const isTime = v => { const t = cellText(v); return t !== '' && /^\d{1,2}[:：]\d{2}(:\d{2})?$/.test(t); };
  E.fmt = min => Math.floor(min / 60) + ':' + ('0' + (min % 60)).slice(-2);

  /** "9:00-12:00" "15-17" "8.5-12/8-13" → [{s,e}] ；不是區間回傳 null */
  function ranges(v) {
    const t = cellText(v).replace(/\s/g, '');
    if (!t || !/\d/.test(t)) return null;
    const parts = t.split(/[\/、,，]/).filter(Boolean);
    const out = [];
    for (const p of parts) {
      const m = p.match(/^(\d{1,2}(?:[:：]\d{2}|\.\d+)?)[-~～〜－—](\d{1,2}(?:[:：]\d{2}|\.\d+)?)$/);
      if (!m) return null;
      const s = hm(m[1]), e = hm(m[2]);
      if (s === null || e === null) return null;
      out.push({ s, e });
    }
    return out.length ? out : null;
  }
  E.ranges = ranges;

  /** 名字格：「林秉承(隔週休)」「鍾偉瑋/林永昌」「李軍逸(超音波)」 → [{name, note}] ；不是名字回傳 null */
  function names(v) {
    const t = cellText(v);
    if (!t || /\d/.test(t)) return null;
    const out = [];
    for (let p of t.split(/[\/、,，]/)) {
      p = p.trim();
      if (!p) continue;
      let note = '';
      p = p.replace(/[（(]([^)）]*)[)）]/g, (_, n) => { note += (note ? '、' : '') + n.trim(); return ''; }).trim();
      if (!CJK.test(p) || STOP.test(p)) return null;
      out.push({ name: p, note });
    }
    return out.length ? out : null;
  }
  E.names = names;

  /** 註記 → { alt:隔週休?, altText, type } */
  function readNote(note, defType) {
    const r = { alt: false, altText: '', type: defType, extra: '' };
    if (!note) return r;
    note.split('、').forEach(n => {
      if (/隔週/.test(n)) { r.alt = true; r.altText = n; }
      else if (/^(減重|超音波|慢箋|疫苗|健檢|兒科|自費|美容|醫美)/.test(n) || defType !== '健保') r.type = n;
      else r.extra += (r.extra ? '、' : '') + n;
    });
    return r;
  }

  /* ---------------------------- 解析班表 ---------------------------- */
  const TITLE_RE = /(\d{1,2})\s*[\/月]\s*(\d{1,2})\s*日?(?:\s*[-~～〜－—]\s*(?:(\d{1,2})\s*[\/月]\s*)?(\d{1,2}))?\s*日?\s*(開始|異動|起|生效|更新)/;

  /** 由試算表名稱「115.10」「115年10月」推月份 → '2026-10' */
  E.monthFromTitle = function (title) {
    const t = toHalf(title || '');
    let m = t.match(/(1\d{2})\s*[.\-\/年]\s*(\d{1,2})/);
    if (m) return (+m[1] + 1911) + '-' + ('0' + m[2]).slice(-2);
    m = t.match(/(20\d{2})\s*[.\-\/年]\s*(\d{1,2})/);
    if (m) return m[1] + '-' + ('0' + m[2]).slice(-2);
    return '';
  };
  E.rocMonth = ym => { const [y, m] = ym.split('-'); return (y - 1911) + '.' + m; };
  E.monthEnd = ym => { const [y, m] = ym.split('-').map(Number); return ym + '-' + ('0' + new Date(y, m, 0).getDate()).slice(-2); };
  const iso = (y, m, d) => y + '-' + ('0' + m).slice(-2) + '-' + ('0' + d).slice(-2);
  function nearYear(mo, ym) {
    const [y, m] = ym.split('-').map(Number);
    if (mo - m > 6) return y - 1;
    if (m - mo > 6) return y + 1;
    return y;
  }
  E.md = d => d ? (+d.slice(5, 7)) + '/' + (+d.slice(8, 10)) : '';

  function isSpecialLabel(label, st) {
    const kws = String(st.specialKeywords || '').split(/[,，、\s]+/).filter(Boolean);
    return kws.some(k => label.indexOf(k) >= 0);
  }
  function specialType(label) {
    const t = label.replace(/(專診|門診|診別|時段)/g, '').trim();
    return t || '特別';
  }
  function sessOf(label) {
    if (/早|上午/.test(label)) return '早';
    if (/午|下午/.test(label) && !/中午/.test(label)) return '午';
    if (/晚|夜/.test(label)) return '晚';
    return '';
  }
  function sessByTime(min, st) {
    if (min >= hm(st.nightStart)) return '晚';
    if (min >= hm(st.noonStart)) return '午';
    return '早';
  }

  /**
   * 解析整本門診表
   * @param book {title, sheets:[{name, grid, merges}]}  （Code.gs readSchedule 的回傳格式）
   * @param opt  {month:'2026-10', clinics:[{clinic, tab, on}], settings}
   */
  E.parseBook = function (book, opt) {
    opt = opt || {};
    const st = opt.settings || E.settings();
    const month = opt.month || E.monthFromTitle(book.title) || '';
    const tabMap = {};
    (opt.clinics || []).forEach(c => { if (c.on !== false) tabMap[c.tab || c.clinic] = c.clinic; });
    const res = { title: book.title, month, clinics: [], warnings: [] };
    book.sheets.forEach(sh => {
      let clinic = tabMap[sh.name];
      if (!clinic) {
        if (opt.clinics && opt.clinics.length) { res.warnings.push('分頁「' + sh.name + '」不在院區清單中，已略過'); return; }
        clinic = sh.name.replace(/(院區|門診|班表)/g, '').trim() || sh.name;
      }
      const c = parseSheet(sh, clinic, month, st);
      if (!c.blocks.length) { res.warnings.push('分頁「' + sh.name + '」找不到「M/D開始」的班表區塊'); return; }
      res.clinics.push(c);
    });
    return res;
  };

  function parseSheet(sh, clinic, month, st) {
    const g = sh.grid;
    const at = (r, c) => (g[r] && g[r][c] !== undefined ? g[r][c] : '');
    const starts = [];
    for (let r = 0; r < g.length; r++) {
      const t = cellText(at(r, 0));
      if (TITLE_RE.test(t)) starts.push(r);
    }
    const blocks = [];
    starts.forEach((r0, i) => {
      const r1 = i + 1 < starts.length ? starts[i + 1] - 1 : g.length - 1;
      const b = parseBlock(g, r0, r1, clinic, month, st);
      if (b) { b.index = blocks.length; blocks.push(b); }
    });
    return { clinic, tab: sh.name, blocks };
  }

  function parseBlock(g, r0, r1, clinic, month, st) {
    const at = (r, c) => (g[r] && g[r][c] !== undefined ? g[r][c] : '');
    const title = cellText(at(r0, 0));
    const m = title.match(TITLE_RE);
    const kind = /異動/.test(m[5]) ? 'temp' : 'base';
    const y = nearYear(+m[1], month || '2000-' + m[1]);
    const start = iso(y, +m[1], +m[2]);
    let end = '';
    if (m[4]) { const em = m[3] ? +m[3] : +m[1]; end = iso(nearYear(em, month || '2000-' + em), em, +m[4]); }
    // 星期列
    let hr = -1;
    for (let r = r0; r <= r1 && hr < 0; r++) for (let c = 1; c < (g[r] || []).length; c++) if (cellText(at(r, c)) === '星期一') { hr = r; break; }
    if (hr < 0) return null;
    const dayCol = [];
    E.DAYS.forEach((d, i) => { for (let c = 1; c < g[hr].length; c++) if (cellText(at(hr, c)) === d || cellText(at(hr, c)) === d.replace('日', '天')) { dayCol[i] = c; break; } });
    if (dayCol.filter(x => x !== undefined).length < 7) return null;
    const width = dayCol[1] - dayCol[0];
    const colDay = {};
    dayCol.forEach((c, i) => { for (let k = 0; k < width; k++) colDay[c + k] = i; });
    const cols = Object.keys(colDay).map(Number).sort((a, b) => a - b);
    // 日期列（週班表才有）
    const dates = [];
    for (let r = hr - 1; r >= r0 && r >= hr - 2; r--) dayCol.forEach((c, i) => { if (isDate(at(r, c))) dates[i] = dateIso(at(r, c)); });
    // 區段（A 欄診別）
    const entries = [];
    let label = '', special = false;
    for (let r = hr + 1; r <= r1; r++) {
      const a = cellText(at(r, 0));
      if (a) { label = a; special = isSpecialLabel(a, st); }
      if (!label) continue;
      for (const c of cols) {
        const nm = names(at(r, c));
        if (!nm) continue;
        const day = colDay[c];
        if (!special && isTime(at(r + 1, c)) && isTilde(at(r + 2, c)) && isTime(at(r + 3, c))) {
          const s = hm(cellText(at(r + 1, c))), e = hm(cellText(at(r + 3, c)));
          nm.forEach(n => push(entries, n, { clinic, day, s, e, sess: sessOf(label) || sessByTime(s, st), defType: '健保', row: r, col: c }));
          continue;
        }
        const rg = ranges(at(r + 1, c));
        if (!rg) continue;
        nm.forEach((n, k) => {
          const x = rg[Math.min(k, rg.length - 1)];
          const defType = special ? specialType(label) : '健保';
          push(entries, n, { clinic, day, s: x.s, e: x.e, sess: special ? sessByTime(x.s, st) : (sessOf(label) || sessByTime(x.s, st)), defType, row: r, col: c });
        });
      }
    }
    return { title, kind, start, end, dates, row: r0 + 1, entries };
  }
  function push(arr, n, o) {
    const nt = readNote(n.note, o.defType);
    if (!(o.e > o.s)) return;
    arr.push({ doctor: n.name, clinic: o.clinic, day: o.day, sess: o.sess, s: o.s, e: o.e, type: nt.type, alt: nt.alt, altText: nt.altText, extra: nt.extra, row: o.row, col: o.col });
  }

  /* ------------------------- 版本判定 ------------------------- */
  /**
   * 依生效日判定各院區採用哪一個「開始」區塊
   * 規則：取「M/D開始」日期 ≤ 生效日中最新的一個（同標題取最上面那張）；「異動」區塊一律不列入基準。
   * @return {picks:{clinic: blockIndex}, info:{clinic:{…}}, upcoming:[{date, clinic, title}], temps:[…]}
   */
  E.pickVersions = function (parsed, date, overrides) {
    overrides = overrides || {};
    const monthEnd = E.monthEnd(parsed.month || date.slice(0, 7));
    const out = { picks: {}, info: {}, upcoming: [], temps: [] };
    parsed.clinics.forEach(c => {
      const bases = c.blocks.filter(b => b.kind === 'base');
      let pick = null, why = '';
      const cand = bases.filter(b => b.start <= date);
      if (cand.length) {
        const maxS = cand.reduce((a, b) => (b.start > a ? b.start : a), '');
        pick = cand.find(b => b.start === maxS);
        why = '最新「開始」版本';
      } else if (bases.length) {
        pick = bases.slice().sort((a, b) => a.start < b.start ? -1 : 1)[0];
        why = '⚠ 所有版本都晚於生效日，暫用最早版本';
      } else { pick = c.blocks[0]; why = '⚠ 找不到「開始」版本，暫用第一張'; }
      if (overrides[c.clinic] !== undefined && c.blocks[overrides[c.clinic]]) { pick = c.blocks[overrides[c.clinic]]; why = '手動指定'; }
      out.picks[c.clinic] = pick.index;
      out.info[c.clinic] = { title: pick.title, start: pick.start, row: pick.row, why, entries: pick.entries.length };
      const seen = {};
      bases.forEach(b => { if (b.start > date && b.start <= monthEnd && b.start > pick.start && !seen[b.start]) { seen[b.start] = 1; out.upcoming.push({ date: b.start, clinic: c.clinic, title: b.title }); } });
      c.blocks.filter(b => b.kind === 'temp').forEach(b => {
        const e = b.end || b.start;
        if (e >= date && b.start <= monthEnd) out.temps.push({ clinic: c.clinic, title: b.title, start: b.start, end: e });
      });
    });
    out.upcoming.sort((a, b) => a.date < b.date ? -1 : 1);
    return out;
  };

  /** 本月所有「開始」日期（供快速選生效日） */
  E.versionDates = function (parsed) {
    const set = {};
    const m = parsed.month;
    parsed.clinics.forEach(c => c.blocks.forEach(b => { if (b.kind === 'base' && b.start.slice(0, 7) === m) (set[b.start] = set[b.start] || []).push(c.clinic); }));
    return Object.keys(set).sort().map(d => ({ date: d, clinics: Array.from(new Set(set[d])) }));
  };

  /* ------------------------- 彙整醫師 ------------------------- */
  /**
   * @param meta 後台醫師清單 [{name, title, home, on, order}]
   * @return [{name, title, home, homeAuto, isNew, entries, cells[sess][day]=[entry…], clinics:[…]}]
   */
  /* ------------------------- 拆班規則 ------------------------- */
  /** 後台「拆班規則」列 → [{doctor, clinic, day(-1=每天), bs, be}] */
  E.normRules = function (rows) {
    return (rows || []).filter(r => r && r.doctor && r.on !== false).map(r => {
      const dt = String(r.day || '').trim();
      let day = -1;
      if (dt && !/每|全/.test(dt)) { const ch = dt.slice(-1); day = '一二三四五六日'.indexOf(ch === '天' ? '日' : ch); }
      return { doctor: String(r.doctor).trim(), clinic: String(r.clinic || '').trim(), day, bs: hm(cellText(r.bs)), be: hm(cellText(r.be)) };
    }).filter(r => r.bs !== null && r.be !== null && r.be > r.bs && r.day >= -1);
  };
  /** 把門診時段扣掉休息時段（例：14:30-21:30 扣 18:30-19:00 → 14:30-18:30、19:00-21:30） */
  function applyBreaks(list, rules, st) {
    if (!rules.length) return list;
    let out = list;
    rules.forEach(r => {
      const next = [];
      out.forEach(e => {
        const hit = (!r.clinic || r.clinic === e.clinic) && (r.day < 0 || r.day === e.day) && e.s < r.be && e.e > r.bs;
        if (!hit) { next.push(e); return; }
        if (e.s < r.bs) next.push(Object.assign({}, e, { e: r.bs, sess: sessByTime(e.s, st), split: true }));
        if (e.e > r.be) next.push(Object.assign({}, e, { s: r.be, sess: sessByTime(r.be, st), split: true }));
      });
      out = next;
    });
    return out;
  }

  E.buildDoctors = function (parsed, picks, meta, st, rules) {
    st = st || E.settings();
    rules = rules || [];
    const metaMap = {};
    (meta || []).forEach(m => { if (m.name) metaMap[m.name] = m; });
    const all = [];
    parsed.clinics.forEach(c => { const b = c.blocks[picks.picks[c.clinic]]; if (b) b.entries.forEach(e => all.push(e)); });
    const byDoc = {};
    all.forEach(e => { (byDoc[e.doctor] = byDoc[e.doctor] || []).push(e); });
    const docs = [];
    Object.keys(byDoc).forEach(name => {
      const m = metaMap[name];
      if (m && m.on === false) return;
      byDoc[name] = applyBreaks(byDoc[name], rules.filter(r => r.doctor === name), st);
      // 去重
      const map = {};
      byDoc[name].forEach(e => {
        const k = [e.clinic, e.day, e.s, e.e, e.type].join('|');
        if (!map[k]) map[k] = Object.assign({}, e);
        else { map[k].alt = map[k].alt && e.alt; if (!map[k].altText) map[k].altText = e.altText; }
      });
      let list = Object.values(map);
      // 特別門診完全包含在同院區同日的健保門診內 → 不另外顯示
      if (String(st.containHide).toUpperCase() !== 'N') {
        const reg = list.filter(e => e.type === '健保');
        list = list.filter(e => e.type === '健保' || !reg.some(r => r.clinic === e.clinic && r.day === e.day && r.s <= e.s && r.e >= e.e));
      }
      list.sort((a, b) => a.day - b.day || E.SESS.indexOf(a.sess) - E.SESS.indexOf(b.sess) || a.s - b.s || (a.type === '健保' ? -1 : 1));
      const auto = autoHome(list);
      const d = {
        name,
        title: (m && m.title) || '醫師',
        home: (m && m.home) || auto,
        homeAuto: !(m && m.home),
        autoHome: auto,
        isNew: !m,
        order: m && m.order !== '' && m.order !== undefined ? +m.order : 9999,
        entries: list.map(e => ({ clinic: e.clinic, day: e.day, sess: e.sess, s: e.s, e: e.e, type: e.type, alt: !!e.alt, altText: e.altText || '', extra: e.extra || '' })),
        clinics: Array.from(new Set(list.map(e => e.clinic)))
      };
      docs.push(d);
    });
    docs.sort((a, b) => a.order - b.order || a.name.localeCompare(b.name, 'zh-Hant'));
    return docs;
  };
  /** 預設專任院區：健保診次最多的院區（同分比時數；沒有健保診則看全部診次） */
  function autoHome(list) {
    const score = {};
    const reg = list.filter(e => e.type === '健保');
    (reg.length ? reg : list).forEach(e => { const s = score[e.clinic] = score[e.clinic] || [0, 0]; s[0]++; s[1] += e.e - e.s; });
    return Object.keys(score).sort((a, b) => score[b][0] - score[a][0] || score[b][1] - score[a][1])[0] || '';
  }
  E.autoHome = autoHome;

  E.cells = function (doc) {
    const cells = E.SESS.map(() => E.DAYS.map(() => []));
    doc.entries.forEach(e => { const si = E.SESS.indexOf(e.sess); if (si >= 0) cells[si][e.day].push(e); });
    return cells;
  };
  /** 班表內容指紋（比對兩次產出是否有異動） */
  E.sig = function (doc) {
    return [doc.title, doc.home].concat(doc.entries.map(e => [e.clinic, e.day, e.sess, e.s, e.e, e.type, e.alt ? 1 : 0].join(','))).join(';');
  };
  E.label = function (e) { return e.clinic + (e.type && e.type !== '健保' ? e.type : ''); };
  E.altLabel = function (e) { return e.alt ? '(' + (e.altText || '隔週休') + ')' : ''; };

  /* ------------------------- 圖卡繪製 ------------------------- */
  const C = {
    bg: '#f8faf9', ink: '#16302b', ink2: '#24514a', muted: '#5f6b68', head: '#2f5a50', headInk: '#ffffff',
    empty: '#eaeeed', homeBg: '#d9efe8', homeBd: '#2f7a6b', homeInk: '#12302a', rowInk: '#4d5a57',
    othBg: '#f4ede6', othBd: '#a98468', othInk: '#5b3f2c', bar: '#2f7a6b', blob: '#b8cbc5'
  };
  E.COLORS = C;
  const FONT = '"Noto Sans TC","Microsoft JhengHei","PingFang TC",sans-serif';
  const SCRIPT = '"Great Vibes","Allura",cursive';
  let logoImg = null;
  E.fontsReady = async function () {
    try {
      if (document.fonts) {
        await Promise.all([
          document.fonts.load('900 40px "Noto Sans TC"', '林院長星期一'),
          document.fonts.load('700 20px "Noto Sans TC"', '鶯歌樹林'),
          document.fonts.load('500 16px "Noto Sans TC"', '隔週休'),
          document.fonts.load('400 40px "Great Vibes"', 'Elite Clinic')
        ]);
      }
    } catch (e) {}
    if (!logoImg) logoImg = await new Promise(res => { const i = new Image(); i.onload = () => res(i); i.onerror = () => res(null); i.src = E.LOGO; });
  };
  function rr(ctx, x, y, w, h, r) {
    r = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y); ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath();
  }
  function fitText(ctx, text, maxW, size, weight, family) {
    let s = size;
    do { ctx.font = weight + ' ' + s + 'px ' + (family || FONT); if (ctx.measureText(text).width <= maxW) break; s -= 1; } while (s > 9);
    return s;
  }
  // 單一門診在格子內的高度（大字直式 / 精簡橫式）
  const BIG = { lab: 20, alt: 14, t: 22, gap: 6 };
  const SM = { lab: 16, alt: 12.5, t: 16, gap: 4 };
  function entryH(e, big) {
    const f = big ? BIG : SM;
    let h = f.lab + (e.alt ? f.alt + 3 : 0) + f.gap;
    h += big ? f.t * 2 + 16 + f.gap * 2 : f.t + 2;
    return h + (big ? 24 : 16);
  }

  /**
   * 繪製個人班表
   * @param doc  buildDoctors 產出的醫師物件
   * @param o    {month:'2026-10', date:'2026-10-15', settings, scale}
   * @return canvas
   */
  E.render = function (doc, o) {
    o = o || {};
    const st = o.settings || E.settings();
    const scale = o.scale || 2;
    const W = 1000, P = 40, LW = 44, GAP = 8;
    const colW = (W - P * 2 - LW - GAP * 7) / 7;
    const cells = E.cells(doc);
    // 列高
    const rowH = cells.map(row => {
      let h = 124;
      row.forEach(list => {
        if (!list.length) return;
        const big = list.length === 1;
        const need = list.reduce((a, e) => a + entryH(e, big), 0) + (list.length - 1) * 6;
        h = Math.max(h, need);
      });
      return Math.ceil(h);
    });
    const headY = 150, headH = 46;
    const gridY = headY + headH + 10;
    const gridH = rowH.reduce((a, b) => a + b, 0) + GAP * 2;
    const H = gridY + gridH + 62;
    const cv = document.createElement('canvas');
    cv.width = W * scale; cv.height = H * scale;
    const ctx = cv.getContext('2d');
    ctx.scale(scale, scale);
    ctx.textBaseline = 'alphabetic';
    // 背景
    ctx.fillStyle = C.bg; ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = C.blob; ctx.globalAlpha = .28;
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(150, 0); ctx.bezierCurveTo(120, 40, 70, 30, 40, 70); ctx.bezierCurveTo(20, 95, 15, 120, 0, 140); ctx.closePath(); ctx.fill();
    ctx.beginPath(); ctx.moveTo(W, H); ctx.lineTo(W - 170, H); ctx.bezierCurveTo(W - 130, H - 40, W - 80, H - 30, W - 45, H - 70); ctx.bezierCurveTo(W - 20, H - 100, W - 12, H - 125, W, H - 150); ctx.closePath(); ctx.fill();
    ctx.globalAlpha = 1;
    // 浮水印
    if (logoImg && st.watermark > 0) {
      const sz = Math.min(gridH * .92, 520);
      ctx.globalAlpha = st.watermark;
      ctx.drawImage(logoImg, (W - sz) / 2 + LW / 2, gridY + (gridH - sz) / 2, sz, sz);
      ctx.globalAlpha = 1;
    }
    // 標題
    const mo = +(o.month || '').slice(5, 7) || '';
    ctx.fillStyle = C.bar; rr(ctx, P, 44, 7, 58, 3.5); ctx.fill();
    ctx.fillStyle = C.ink;
    ctx.font = '900 44px ' + FONT;
    ctx.fillText(doc.name, P + 22, 90);
    let x = P + 22 + ctx.measureText(doc.name).width + 12;
    ctx.font = '700 28px ' + FONT; ctx.fillStyle = C.ink2;
    ctx.fillText(doc.title || '', x, 89);
    x += ctx.measureText(doc.title || '').width + 16;
    // 月份膠囊
    const mTxt = mo + '月門診表';
    ctx.font = '700 19px ' + FONT;
    const mw = ctx.measureText(mTxt).width + 28;
    ctx.fillStyle = C.head; rr(ctx, x, 60, mw, 34, 17); ctx.fill();
    ctx.fillStyle = '#fff'; ctx.fillText(mTxt, x + 14, 84);
    // 副標
    const d1 = o.date && +o.date.slice(8, 10) !== 1 ? E.md(o.date) + ' 起適用 · ' : '';
    ctx.font = '500 16px ' + FONT; ctx.fillStyle = C.muted;
    ctx.fillText('個人班表 · ' + d1 + (st.notice || ''), P + 22, 124);
    // 圖例
    if (String(st.showLegend).toUpperCase() !== 'N') {
      ctx.font = '500 15px ' + FONT;
      const items = [[st.homeLabel, C.homeBg, C.homeBd], [st.otherLabel, C.othBg, C.othBd]];
      let lx = W - P;
      items.slice().reverse().forEach(([t, bg, bd]) => {
        const tw = ctx.measureText(t).width;
        lx -= tw; ctx.fillStyle = C.muted; ctx.fillText(t, lx, 124);
        lx -= 26; ctx.fillStyle = bg; rr(ctx, lx, 110, 18, 18, 5); ctx.fill(); ctx.strokeStyle = bd; ctx.lineWidth = 1.5; ctx.stroke();
        lx -= 20;
      });
      // 右上 logo
      if (logoImg) ctx.drawImage(logoImg, W - P - 70, 30, 70, 70);
    }
    // 星期列
    E.DAYS.forEach((d, i) => {
      const cx = P + LW + GAP + i * (colW + GAP);
      ctx.fillStyle = C.head; rr(ctx, cx, headY, colW, headH, 12); ctx.fill();
      ctx.fillStyle = C.headInk; ctx.font = '700 19px ' + FONT; ctx.textAlign = 'center';
      ctx.fillText(d, cx + colW / 2, headY + 30);
      ctx.textAlign = 'left';
    });
    // 格子
    let y = gridY;
    cells.forEach((row, si) => {
      const h = rowH[si];
      ctx.fillStyle = C.rowInk; ctx.font = '700 19px ' + FONT; ctx.textAlign = 'center';
      ctx.fillText(E.SESS[si], P + LW / 2 - 4, y + h / 2 - 3);          // 直立：早 / 診
      ctx.fillText('診', P + LW / 2 - 4, y + h / 2 + 21);
      row.forEach((list, di) => {
        const cx = P + LW + GAP + di * (colW + GAP);
        if (!list.length) { ctx.fillStyle = C.empty; rr(ctx, cx, y, colW, h, 12); ctx.fill(); return; }
        const big = list.length === 1;
        const need = list.map(e => entryH(e, big));
        const extra = (h - need.reduce((a, b) => a + b, 0) - (list.length - 1) * 6) / list.length;
        let ey = y;
        list.forEach((e, k) => {
          const eh = need[k] + extra;
          const home = e.clinic === doc.home;
          ctx.fillStyle = home ? C.homeBg : C.othBg; rr(ctx, cx, ey, colW, eh, 12); ctx.fill();
          ctx.strokeStyle = home ? C.homeBd : C.othBd; ctx.lineWidth = home ? 2 : 1.5; rr(ctx, cx + .8, ey + .8, colW - 1.6, eh - 1.6, 11.5); ctx.stroke();
          drawEntry(ctx, e, cx, ey, colW, eh, big, home ? C.homeInk : C.othInk);
          ey += eh + 6;
        });
      });
      ctx.textAlign = 'left';
      y += h + GAP;
    });
    // 頁尾
    ctx.textAlign = 'center';
    ctx.fillStyle = C.ink2; ctx.font = '400 30px ' + SCRIPT;
    ctx.fillText(st.footer || 'Elite Clinic', W / 2, H - 20);
    ctx.textAlign = 'left';
    return cv;
  };
  function drawEntry(ctx, e, x, y, w, h, big, ink) {
    const f = big ? BIG : SM;
    const inner = w - 12;
    const lab = E.label(e);
    const content = entryH(e, big) - (big ? 24 : 16);
    let cy = y + (h - content) / 2;
    ctx.textAlign = 'center'; ctx.fillStyle = ink;
    const ls = fitText(ctx, lab, inner, f.lab, 700);
    cy += ls; ctx.fillText(lab, x + w / 2, cy);
    if (e.alt) {
      fitText(ctx, E.altLabel(e), inner, f.alt, 700);
      cy += f.alt + 3; ctx.fillText(E.altLabel(e), x + w / 2, cy);
    }
    cy += f.gap;
    if (big) {
      ctx.font = '700 ' + f.t + 'px ' + FONT;
      cy += f.t; ctx.fillText(E.fmt(e.s), x + w / 2, cy);
      ctx.fillRect(x + w / 2 - 1, cy + 5, 2, 10);
      cy += 16 + f.gap + f.t; ctx.fillText(E.fmt(e.e), x + w / 2, cy);
    } else {
      fitText(ctx, E.fmt(e.s) + '–' + E.fmt(e.e), inner, f.t, 700);
      cy += f.t; ctx.fillText(E.fmt(e.s) + '–' + E.fmt(e.e), x + w / 2, cy);
    }
    ctx.textAlign = 'left';
  }

  E.toBlob = cv => new Promise(res => cv.toBlob(res, 'image/png'));
  E.fileName = doc => doc.name + '.png';

  if (typeof module !== 'undefined' && module.exports) module.exports = E;
  root.E = E;
})(typeof window !== 'undefined' ? window : globalThis);
